// safe-stage-v3
try{
if ($input.first().json.body?.platform_configs || $input.first().json.platform_configs) throw new Error('Send one platform per workflow request');
const payload = $input.first().json;
let body = payload.body ?? payload;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = { raw_material: body }; }
}
const now = new Date().toISOString();

for (const [key, fallback, min, max] of [['max_rounds', 2, 0, 10], ['pass_score', 25, 0, 100]]) {
  const value = body[key] ?? fallback;
  if (typeof value !== "number" || !Number.isInteger(value) || value < min || value > max) throw new Error('Invalid ' + key);
  body[key] = value;
}
if (body.language && !['zh', 'en'].includes(body.language)) throw new Error('Workflow supports one language per request: zh or en');

// editorial-context-v2
const samples=body.author_samples ?? []; const facts=body.facts ?? []; const forbidden=body.forbidden_claims ?? [];
if (!Array.isArray(samples)||samples.some(s=>typeof s!=='string'||!s.trim())) throw new Error('Invalid author_samples');
if (!Array.isArray(forbidden)||forbidden.some(s=>typeof s!=='string')) throw new Error('Invalid forbidden_claims');
if (!Array.isArray(facts)||facts.some(f=>!f||['id','claim','source'].some(k=>typeof f[k]!=='string'||!f[k].trim()))||new Set(facts.map(f=>f.id)).size!==facts.length) throw new Error('Invalid facts');
const thresholds={...{"style_min_score":60,"expression_min_score":60,"distribution_min_score":60,"viral_min_score":40,"calibration_status":"uncalibrated","policy":"Unknown or failed dimensions require review. Facts cannot be offset by other scores. Scores do not predict reach.","calibration":"Collect human-reviewed good and bad drafts, including false positives; compare model judgments against held-out examples. Record model and prompt versions. Change thresholds only after human review."},...(body.review_thresholds ?? {})};
for(const key of ['style_min_score','expression_min_score','distribution_min_score','viral_min_score']) if(typeof thresholds[key]!=='number'||!Number.isFinite(thresholds[key])||thresholds[key]<0||thresholds[key]>100) throw new Error('Invalid threshold');
// style-guidance-v3
if(body.style_guidance!==undefined&&typeof body.style_guidance!=='string')throw new Error('Invalid style_guidance');
