// safe-stage-v3
try{

function textOf(res) {
  for (const value of [res.output, res.text, res.response, res.content, res.message?.content, res.choices?.[0]?.message?.content]) {
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  throw new Error('Empty model output');
}
function parse(res) {
  const raw = textOf(res).replace(/^```(?:json)?\s*/i, '').replace(/```$/,'').trim();
  const value = JSON.parse(raw);
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Expected object');
  return value;
}
function score(value) { return typeof value === 'number' && Number.isFinite(value) && value >= 0 && value <= 100; }

const base = $('Parse Structure').first().json;
const text = textOf($input.first().json);
return [{json: {...base, draft_v0: text, current_text: text, versions: {draft_v0: text}, round: 0}}];
}catch(error){let base={};try{base=$('Parse Structure').first().json;}catch(_){}const text=base.final_text??base.current_text??base.raw_material??'';return [{json:{...base,ok:false,execution_mode:'strict_model_workflow',language:base.language??'zh',status:'needs_human_review',final_text:text,ai_slop_score:100,platform_output:base.platform_output??{title_options:[base.title??''],selected_title:base.title??'',summary:'',body:text,tags:[],publish_notes:error.message,files:[]},stage_error:true,failed_stage:"Parse Draft V0",error:error.message}}];}

const item = $input.first().json;
const text = item.current_text || '';
const config = {"zh":{"blacklist":["在当今时代","随着技术不断发展","随着.*发展","信息爆炸的时代","不难发现","值得注意的是","赋能","闭环","新范式","底层逻辑","深度融合","全面提升","高效协同","未来可期","降本增效","打破边界","重塑格局","显著提升","极具价值","革命性","颠覆式","无缝","强大","高效","全面","深度","重要","助力","赋予","推动.*发展"],"meta":["接下来我们将","本文将探讨","通过以上分析","综上所述","总而言之","在上一节中","我们已经了解了","本节将","从.*角度来看","可以看出","由此可见"]},"en":{"blacklist":["in today's fast-paced world","as technology continues to evolve","in the digital age","game-changer","revolutionary","seamless","robust","leverage","unlock","empower","transformative","cutting-edge","at scale","paradigm shift","unlock the potential","drive innovation","enhance productivity","streamline workflows","it is important to note","delve into"],"meta":["this article will explore","in this article, we will","in conclusion","to summarize","as we have seen","it is worth noting","let's dive in","we will discuss"]},"weights":{"blacklist_hit_weight":6,"meta_phrase_hit_weight":8,"repeated_sentence_start_weight":5,"paragraph_symmetry_penalty":15,"list_overuse_penalty":12,"generic_opening_penalty":12,"generic_ending_penalty":12,"vague_claim_hit_weight":7,"abstract_noun_density_penalty":10,"weak_ending_penalty":26,"low_specificity_penalty":10,"max_score":100,"levels":[{"min":0,"max":25,"label":"pass","action":"human_review"},{"min":26,"max":45,"label":"light_rewrite","action":"targeted_rewrite"},{"min":46,"max":70,"label":"heavy_rewrite","action":"restructure_and_rewrite"},{"min":71,"max":100,"label":"restructure_required","action":"return_to_structure_planning"}]}};
const en = item.language === 'en';
const rules = config[en ? 'en' : 'zh'];
const w = config.weights;
const hits = patterns => patterns.map(pattern => ({pattern,count:(text.match(new RegExp(pattern,'gi')) || []).length})).filter(h=>h.count);
const blacklist = hits(rules.blacklist);
const meta = hits(rules.meta);
const sentences = text.split(/(?<=[。！？!?\.])\s*/).filter(Boolean);
const paragraphs = text.split(/\n+/).filter(Boolean);
const tail = sentences.at(-1) || '';
const vaguePatterns = en ? ['increasingly important','play(?:s)? a [^.!?]{0,60} role','deliver [^.!?]{0,60} value','improve [^.!?]{0,60} efficiency','unlock [^.!?]{0,60} potential'] : ['越来越重要','发挥[^。！？]{0,60}作用','带来[^。！？]{0,60}价值','提升[^。！？]{0,60}效率','提高[^。！？]{0,60}质量'];
const vague = hits(vaguePatterns);
const weak = (en ? /increasingly important|unlock .* potential|drive .* value|play.*role/i : /越来越重要|未来可期|发挥.{0,40}作用|带来.{0,40}价值|值得.{0,40}关注/).test(tail);
const specific = (text.match(en ? /\d+|\bwhen\b|\bbefore\b|\bafter\b|\bfor example\b|\bbecause\b/gi : /\d+|比如|例如|一次|当时|后来|因为|具体|限制|代价|取舍/g)||[]).length;
const opening = (en ? /^(in today's|in today’s|as technology continues)/i : /^(在当今|随着|近年来|如今|当前|现在)/).test(text.trim());
const ending = /总而言之|综上所述|未来.*越来越重要|未来可期|让我们.*未来/.test(tail);
const starts = {}; for (const sentence of sentences) { const key=sentence.slice(0,8); starts[key]=(starts[key]||0)+1; }
const repeated = Object.entries(starts).filter(([k,v])=>v>=3).map(([start,count])=>({start,count}));
const average = paragraphs.reduce((sum,p)=>sum+p.length,0)/Math.max(paragraphs.length,1);
const symmetry = paragraphs.filter(p=>Math.abs(p.length-average)/Math.max(average,1)<0.15).length/Math.max(paragraphs.length,1);
const lists = text.split('\n').filter(line=>/^\s*(\d+[.、]|[-*•]|[一二三四五六七八九十]+[、.])/.test(line)).length/Math.max(paragraphs.length,1);
const terms = en ? ['value','efficiency','quality','system','framework','approach','model','impact','potential','strategy','solution','innovation'] : ['能力','价值','效率','质量','体系','系统','方法','路径','机制','模型','场景','生态','趋势','影响','意义'];
const density = terms.reduce((sum,t)=>sum+(text.match(new RegExp(t,'gi'))||[]).length,0)/Math.max(sentences.length,1);
const deep = vague.reduce((sum,h)=>sum+h.count*w.vague_claim_hit_weight,0)+(weak?w.weak_ending_penalty:0)+(specific===0&&sentences.length>=3?w.low_specificity_penalty:0)+(density>=2&&sentences.length>=3?w.abstract_noun_density_penalty:0);
const score = Math.min(w.max_score,blacklist.reduce((sum,h)=>sum+h.count*w.blacklist_hit_weight,0)+meta.reduce((sum,h)=>sum+h.count*w.meta_phrase_hit_weight,0)+repeated.reduce((sum,h)=>sum+h.count*w.repeated_sentence_start_weight,0)+(opening?w.generic_opening_penalty:0)+(ending?w.generic_ending_penalty:0)+(symmetry>0.7&&paragraphs.length>=5?w.paragraph_symmetry_penalty:0)+(lists>0.5&&paragraphs.length>=6?w.list_overuse_penalty:0)+deep);
return [{json:{...item,rule_scan:{ai_slop_rule_score:score,blacklist_hits:blacklist,meta_hits:meta,repeated_starts:repeated,vague_claim_hits:vague,weak_ending:weak,specificity_marker_count:specific,abstract_noun_density:density,deep_slop_score:deep,generic_opening:opening,generic_ending:ending,paragraph_count:paragraphs.length,sentence_count:sentences.length,symmetry_ratio:symmetry,list_ratio:lists}}}];

function textOf(res) {
  for (const value of [res.output, res.text, res.response, res.content, res.message?.content, res.choices?.[0]?.message?.content]) {
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  throw new Error('Empty model output');
}
function parse(res) {
  const raw = textOf(res).replace(/^```(?:json)?\s*/i, '').replace(/```$/,'').trim();
  const value = JSON.parse(raw);
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Expected object');
  return value;
}
function score(value) { return typeof value === 'number' && Number.isFinite(value) && value >= 0 && value <= 100; }

const base = $('Rule Scan').all(0, $runIndex)[0].json;
let judge;
try {
  judge = parse($input.first().json);
  if (!score(judge.ai_slop_score) || !['pass','rewrite','human_review'].includes(judge.verdict) || !Array.isArray(judge.issues) || typeof judge.rewrite_brief !== 'string') throw new Error('Invalid Judge');
} catch (error) {
  judge = {ai_slop_score: 100, verdict: 'human_review', main_problem: error.message, issues: [], rewrite_brief: 'Model response requires human review.'};
}
const overall = Math.max(judge.ai_slop_score, base.rule_scan.ai_slop_rule_score);
return [{json: {...base, judge_result: judge, overall_ai_slop_score: overall, requires_human_review: judge.verdict === 'human_review'}}];

