function parse(res){const raw=res.text??res.output??res.response??res.content; if(typeof raw!=='string') throw new Error('Missing model response');const data=JSON.parse(raw.replace(/^```(?:json)?\s*/i,'').replace(/```$/,'').trim());if(!data||typeof data!=='object'||Array.isArray(data)) throw new Error('Expected object');return data;}
function validScore(value){return typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=100;}

function publicationText(item) {
 const p=item.platform_output??{};
 return [item.selected_title??item.title,p.cover_text??item.cover_text??'',p.summary??'',item.final_text??p.body??'',...(p.hook_lines??[]),...(p.tags??[])].join('\n');
}
function validatePublication(output) {
 const schema={"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"title_options":{"type":"array","items":{"type":"string"}},"summary":{"type":"string"},"body":{"type":"string"},"tags":{"type":"array","items":{"type":"string"}},"cover_prompt":{"type":"string"},"image_style":{"type":"string","enum":["sketch","editorial","documentary","infographic","hand-drawn","none"]},"image_usage":{"type":"string","enum":["cover","section","social_card","none"]},"image_reason":{"type":"string"},"hook_lines":{"type":"array","items":{"type":"string"}},"share_trigger":{"type":"string"},"comment_trigger":{"type":"string"},"publish_notes":{"type":"string"},"files":{"type":"array","items":{"type":"string"}},"selected_title":{"type":"string","minLength":1},"cover_text":{"type":"string"},"layout_plan":{"type":"object","properties":{"platform":{"type":"string","enum":["wechat","toutiao","xiaohongshu","douyin_long_text","douyin_video","wechat_channels","weibo","zhihu","bilibili","bilibili_video","baijiahao","kuaishou","juejin","csdn","jianshu","medium","substack","linkedin","linkedin_article","x_thread","threads","instagram","instagram_reels","tiktok","youtube_community","youtube","youtube_shorts","facebook","reddit","pinterest","quora","blog","seo_article","generic"]},"format":{"type":"string","enum":["long_form","text","short_post","thread","spoken","carousel","script"]},"blocks":{"type":"array","items":{"type":"object","properties":{"index":{"type":"integer","minimum":1},"kind":{"type":"string","enum":["post","card","speech","paragraph","section"]},"text":{"type":"string"}},"required":["index","kind","text"]}},"publishing_steps":{"type":"array","items":{"type":"string"}},"warnings":{"type":"array","items":{"type":"string"}}},"required":["platform","format","blocks","publishing_steps","warnings"]}},"required":["title_options","summary","body","tags","publish_notes","files"]};
 for(const key of [...schema.required.filter(k=>k!=='files'),'selected_title']) if(!(key in output))throw new Error('Missing publication field '+key);
 for(const [key,spec] of Object.entries(schema.properties)) {
  if(!(key in output)||key==='files'||key==='layout_plan')continue;
  const value=output[key];
  if(spec.type==='string'&&typeof value!=='string')throw new Error('Invalid publication field '+key);
  if(spec.type==='array'&&(!Array.isArray(value)||value.some(v=>typeof v!==spec.items.type)))throw new Error('Invalid publication field '+key);
  if(spec.enum&&!spec.enum.includes(value))throw new Error('Invalid publication field '+key);
 }
 if(!output.body.trim()||!output.title_options.length||output.title_options.some(t=>!t.trim())||!output.title_options.includes(output.selected_title))throw new Error('Invalid publication title/body');
}

const base=$('Prepare Final').first().json;
let output;let status=base.status;let platform_error=false;
try{output=parse($input.first().json);validatePublication(output);}
catch(error){platform_error=true;status='needs_human_review';output={selected_title:base.title,title_options:[base.title],body:base.final_text,tags:[],summary:'',publish_notes:error.message};}
return [{json:{...base,status,platform_error,title:output.selected_title,selected_title:output.selected_title,title_options:output.title_options,cover_text:output.cover_text??'',final_text:output.body,platform_output:{...output,format:base.format??"text",layout_plan:publicationLayout(base,output.body),files:[]}}}];

